"""Exact solvers written from the problem definitions in problems.py.

solve_vertex_cover is a straightforward brute force over vertex subsets.
solve_sat is an exact DPLL search with unit propagation (still a complete
solver, just fast enough to check the reductions on small instances).
"""

from __future__ import annotations

from itertools import combinations


def solve_vertex_cover(instance: dict) -> bool:
    """True iff the graph has a vertex cover of size at most k."""
    n = instance["n"]
    edges = instance["edges"]
    k = instance["k"]
    if k < 0:
        return False
    for size in range(0, min(k, n) + 1):
        for chosen in combinations(range(n), size):
            chosen = set(chosen)
            if all(u in chosen or v in chosen for (u, v) in edges):
                return True
    return False


def solve_sat(instance: dict) -> bool:
    """True iff some assignment satisfies every clause (exact DPLL)."""
    clauses = [list(c) for c in instance["clauses"]]

    def simplify(clauses, lit):
        """Apply assignment lit=True; return None on conflict, else new clauses."""
        new_clauses = []
        for clause in clauses:
            if lit in clause:
                continue
            reduced = [x for x in clause if x != -lit]
            if not reduced:
                return None
            new_clauses.append(reduced)
        return new_clauses

    def dpll(clauses):
        # Unit propagation.
        while True:
            unit = None
            for clause in clauses:
                if len(clause) == 1:
                    unit = clause[0]
                    break
            if unit is None:
                break
            clauses = simplify(clauses, unit)
            if clauses is None:
                return False
        if not clauses:
            return True
        # Choose the literal occurring most often.
        counts = {}
        for clause in clauses:
            for lit in clause:
                counts[lit] = counts.get(lit, 0) + 1
        best = max(counts, key=lambda l: counts[l])
        for choice in (best, -best):
            nxt = simplify(clauses, choice)
            if nxt is not None and dpll(nxt):
                return True
        return False

    return dpll(clauses)
EOF
